from __future__ import annotations

import ast
import io
import re
import tokenize
from dataclasses import dataclass
from pathlib import PurePosixPath
from typing import TYPE_CHECKING

from style_scan import Comment, Finding, Lexer, count_lines, find_closing_brace, first_code_line

if TYPE_CHECKING:
    from collections.abc import Callable

MAX_LINES = 600
COOKIE_LAST_LINE = 2

LANGUAGES: dict[str, str] = {
    ".rs": "rust",
    ".cs": "csharp",
    ".py": "python",
    ".ps1": "powershell",
    ".psm1": "powershell",
    ".psd1": "powershell",
    ".sh": "shell",
    ".bash": "shell",
    ".ts": "typescript",
    ".tsx": "typescript",
    ".mts": "typescript",
    ".cts": "typescript",
    ".js": "typescript",
    ".mjs": "typescript",
    ".cjs": "typescript",
    ".jsx": "typescript",
    ".svelte": "typescript",
    ".vue": "typescript",
    ".astro": "typescript",
    ".css": "css",
    ".scss": "preprocessed",
    ".sass": "preprocessed",
    ".less": "preprocessed",
    ".styl": "preprocessed",
}
SHELL_TEMPLATE = re.compile(r"\.(?:sh|bash)\.tpl$")
SHELL_SHEBANG = re.compile(r"^#![ \t]*\S*/(?:env[ \t]+(?:-\S+[ \t]+)*)?(?:ba|da|k|z)?sh\b")
PYTHON_SHEBANG = re.compile(r"^#![ \t]*\S*/(?:env[ \t]+(?:-\S+[ \t]+)*)?python[0-9.]*\b")
CODING_COOKIE = re.compile(r"^[ \t\f]*#.*?coding[:=][ \t]*[-\w.]+")
LICENCE = re.compile(r"SPDX-License-Identifier|Copyright|Licensed under|GNU General Public License", re.IGNORECASE)
HEADER_DIRECTIVES = (
    r"\b(?:pyright|mypy|ruff|fmt|isort|pylint)\s*:",
    r"\bnoqa\b",
    r"\btype\s*:\s*ignore\b",
    r"<auto-generated",
    r"\bReSharper\s+disable\b",
    r"\bshellcheck\s+disable\b",
    r"\beslint-disable\b",
)
HEADER_DIRECTIVE = re.compile("|".join(HEADER_DIRECTIVES), re.IGNORECASE)

RUST_SUPPRESSION = re.compile(r"#!?\[\s*(?:allow|expect)\s*\(")
RUST_CFG_ATTR = re.compile(r"#!?\[\s*cfg_attr\s*\(")
RUST_ALLOW_INSIDE = re.compile(r"\b(?:allow|expect)\s*\(")
RUST_TEST_MODULE = re.compile(
    r"#\[\s*cfg\s*\(\s*test\s*\)\s*\](?:\s*#\[[^\]]*\])*\s*(?:pub(?:\s*\([^)]*\))?\s+)?mod\s+\w+\s*\{",
)
CSHARP_SUPPRESSION = re.compile(r"\b(?:Unconditional)?SuppressMessage(?:Attribute)?\b")
CSHARP_GENERATED_ATTRIBUTE = re.compile(
    r"[\[,]\s*(?:\w+\s*:\s*)?(?:global::)?(?:System\.CodeDom\.Compiler\.)?GeneratedCode(?:Attribute)?\s*[(\],]",
)
CSHARP_DIRECTIVE = re.compile(
    r"^\s*#\s*(?:pragma\s+warning\s+disable|nullable\s+(?:disable|enable\s+annotations))\b",
)
GENERATED_NAME = re.compile(r"\.(?:g|g\.i|generated)\.cs$|(?:^|/)TemporaryGeneratedFile_[^/]*\.cs$", re.IGNORECASE)
DESIGNER_NAME = re.compile(r"\.designer\.cs$", re.IGNORECASE)


@dataclass(frozen=True, slots=True)
class RustReport:
    findings: list[Finding]
    lines: int


def comment_findings(
    path: str,
    comments: list[Comment],
    first_code: int,
    keep: Callable[[Comment], bool],
) -> list[Finding]:
    header = [comment for comment in comments if comment.line < first_code]
    licensed = any(LICENCE.search(comment.text) for comment in header)
    header_lines = {comment.line for comment in header} if licensed else set[int]()
    findings: list[Finding] = []
    for comment in comments:
        if comment.line in header_lines:
            if HEADER_DIRECTIVE.search(comment.text):
                findings.append(Finding(path, comment.line, "tool directive in the licence header (GEN-4)"))
            continue
        if not keep(comment):
            findings.append(Finding(path, comment.line, "comment (GEN-29)"))
    return findings


def is_safety_comment(comment: Comment) -> bool:
    body = comment.text
    return body.startswith("//") and not body.startswith(("///", "//!")) and body[2:].lstrip().startswith("SAFETY:")


def is_never_kept(_comment: Comment) -> bool:
    return False


def is_python_preamble(comment: Comment) -> bool:
    if comment.line == 1 and comment.text.startswith("#!"):
        return True
    return comment.line <= COOKIE_LAST_LINE and CODING_COOKIE.match(comment.text) is not None


def check_rust(path: str, text: str) -> RustReport:
    scan = Lexer(text, rust=True).run()
    code = "".join(scan.code)
    findings = comment_findings(path, scan.comments, first_code_line(scan), is_safety_comment)
    findings.extend(
        Finding(path, scan.line_of(match.start()), "lint suppression (GEN-4)")
        for match in RUST_SUPPRESSION.finditer(code)
    )
    for match in RUST_CFG_ATTR.finditer(code):
        end = code.find("]", match.end())
        if RUST_ALLOW_INSIDE.search(code[match.end() : len(code) if end < 0 else end]):
            findings.append(Finding(path, scan.line_of(match.start()), "lint suppression (GEN-4)"))
    test_lines = 0
    for match in RUST_TEST_MODULE.finditer(code):
        close = find_closing_brace(code, match.end() - 1)
        test_lines += scan.line_of(close) - scan.line_of(match.start()) + 1
    return RustReport(findings, count_lines(text) - test_lines)


def check_csharp(path: str, text: str) -> list[Finding]:
    scan = Lexer(text, rust=False).run()
    code = "".join(scan.code)
    findings = comment_findings(path, scan.comments, first_code_line(scan), is_never_kept)
    findings.extend(
        Finding(path, directive.line, "lint suppression (GEN-4)")
        for directive in scan.directives
        if CSHARP_DIRECTIVE.match(directive.text)
    )
    findings.extend(
        Finding(path, scan.line_of(match.start()), "lint suppression (GEN-4)")
        for match in CSHARP_SUPPRESSION.finditer(code)
    )
    findings.extend(
        Finding(path, scan.line_of(match.start()), "GeneratedCode attribute hides the type from analyzers (GEN-4)")
        for match in CSHARP_GENERATED_ATTRIBUTE.finditer(code)
    )
    return findings


def check_python(path: str, text: str) -> list[Finding]:
    comments: list[Comment] = []
    first_code = 0
    try:
        for token in tokenize.generate_tokens(io.StringIO(text).readline):
            if token.type == tokenize.COMMENT:
                comments.append(Comment(token.start[0], token.string))
            elif not first_code and token.type not in {tokenize.NL, tokenize.NEWLINE, tokenize.ENCODING}:
                first_code = token.start[0]
        tree = ast.parse(text, filename=path)
    except (SyntaxError, tokenize.TokenError) as error:
        return [Finding(path, getattr(error, "lineno", 0) or 0, f"can't parse: {error}")]
    findings = comment_findings(path, comments, first_code or len(text.splitlines()) + 1, is_python_preamble)
    findings.extend(
        Finding(path, node.lineno, "docstring or string used as a comment (GEN-29)")
        for node in ast.walk(tree)
        if isinstance(node, ast.Expr) and isinstance(node.value, ast.Constant) and isinstance(node.value.value, str)
    )
    return findings


def language_of(path: str, text: str) -> str | None:
    name = path.rsplit("/", 1)[-1]
    if SHELL_TEMPLATE.search(name):
        return "shell"
    suffix = PurePosixPath(name).suffix.lower()
    if suffix:
        return LANGUAGES.get(suffix)
    first = text.split("\n", 1)[0]
    if SHELL_SHEBANG.match(first):
        return "shell"
    if PYTHON_SHEBANG.match(first):
        return "python"
    return None


def check_source(path: str, text: str) -> list[Finding]:
    language = language_of(path, text)
    if language is None:
        return []
    if language == "preprocessed":
        return [Finding(path, 0, "Sass, Less or Stylus file; write plain CSS (CSS-10)")]
    findings: list[Finding] = []
    lines = count_lines(text)
    if language == "rust":
        report = check_rust(path, text)
        findings.extend(report.findings)
        lines = report.lines
    elif language == "csharp":
        findings.extend(check_csharp(path, text))
    elif language == "python":
        findings.extend(check_python(path, text))
    if lines > MAX_LINES:
        findings.append(Finding(path, 0, f"{lines} lines, over {MAX_LINES} (GEN-15)"))
    return findings


def check_generated(path: str, tracked: frozenset[str]) -> list[Finding]:
    if GENERATED_NAME.search(path):
        return [Finding(path, 0, "generated C# file is committed, and analyzers skip it (GEN-4)")]
    match = DESIGNER_NAME.search(path)
    if match and path[: match.start()] + ".cs" not in tracked:
        return [Finding(path, 0, "Designer.cs with no same-name .cs, so analyzers skip it (GEN-4)")]
    return []
